def create_student_table(self):
    try:
        self.connection = sqlite3.connect(self.database_name)
        self.cursor = self.connection.cursor()
        self.cursor.execute('\n                CREATE TABLE IF NOT EXISTS students (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    name TEXT NOT NULL,\n                    age INTEGER NOT NULL,\n                    gender TEXT NOT NULL,\n                    grade INTEGER NOT NULL\n                )\n            ')
        self.connection.commit()
    except sqlite3.Error as v0:
        print(f'Error creating table: {v0}')
        self.connection.close()
    finally:
        if self.cursor:
            self.cursor.close()
        if self.connection:
            self.connection.close()

